from collections import deque

def max_candies(n, m, allowances):
    N = len(allowances)
    candies = [m] * (N + 1)
    queue = deque([(1, candies[0])])

    while queue:
        current_turn, total_allowance = queue.popleft()
        if current_turn == N:
            continue

        if total_allowance == candies[current_turn] + (total_allowance * 2) // (current_turn + 1):
            for i in range(current_turn + 2, m + 1):
                if candies[i] is None:
                    candies[i] = total_allowance + total_allowance // (i + 1) - 1
                    queue.append((i, total_allowance + total_allowance // (i + 1) - 1))

        if total_allowance < candies[current_turn]:
            for i in range(current_turn + 2, m + 1):
                new_allowance = total_allowance + total_allowance // (i + 1) - 1
                if new_allowance >= candies[i]:
                    if candies[i] is None:
                        candies[i] = new_allowance
                        queue.append((i, new_allowance))

    return max(candies[i] for i in range(m + 1) if i < N + 1 and candies[i] is not None)

# Example usage
print(max_candies(2, 5, [5, 10]))  # Output: 13
print(max_candies(3, 8, [8, 16, 13]))  # Output: 32
