from collections import defaultdict

def learnable_recipes(N, intervals, Q, groups, queries):
    present = defaultdict(list)
    for i, interval in enumerate(intervals):
        present[(interval[0], interval[1])].append(i+1)

    def learn(group):
        visited = set()
        for index in group:
            recipe = present[(index, index+1)]
            for i in range(1, len(recipe) - 1):
                visited.add(recipe[i-1])
                visited.add(recipe[i])
                visited.add(recipe[i+1])
        return len(visited)

    results = []
    for query in queries:
        if len(query) > 1:
            results.append(sum(learn(part) for part in query))
        else:
            results.append(learn(query[0]))

    return results

