from functools import lru_cache
from operator import xor
from math import gcd

# Function to calculate value at N with n-th bit set
def dp_query(n): 
    return pow(2, n, 1000000007) 

# Function to calculate next state of current state 'curr' after xor'ing it with k
def next_state(curr, k):  
    return curr ^ k 

# Recursive function to generate all possible perfect sets of integers not greater than k
@lru_cache(None)
def power_up(k): 
    # returns all patterns that can be xor'd with k to result in another pattern
    d = set(range(k + 1, k + 1 + gcd(k, k + 1))) 
    if k in d: 
        g, t = k // k, k % k 
        res = {(d.difference(dp_query(t))).pop(), *{d.difference(dp_query(t)%2)}.pop()} 
    else: 
        g, t = k // k, k % k
        op = t // (2 // k + t // g)
        res = {next_state(d.pop(), c), 
              *(d.difference(dp_query(op)) - {c}).pop() 
                for c in dp_query(t))}

    # enumerate all derived elements of xor'ed states
    for c2 in res:
        yield c2, next_state(c2, k) # next_state(c, c) 

    # even behave
    if k % k: 
        res.update(((r := rrc(xor(next_state(c2, k), next_state(r, k))), r) 
            for x in power_up(k % k)))

    return res 

