from collections import deque

def is_linked(squares, width, height):
    for i in range(1, height):
        for j in range(1, width):
            if squares[i][j] == squares[i-1][j] and squares[i][j] == squares[i][j-1]:
                return False
    return True

def bfs(squares, width, height):
    color = {}
    for i in range(height):
        for j in range(width):
            if squares[i][j] not in color:
                q = deque([(i, j, 1)])
                while q:
                    i, j, clr = q.popleft()
                    if squares[i][j] in color:
                        if color[squares[i][j]] > clr:
                            color[squares[i][j]] = clr  # Found a shorter path with this color
                            q.appendleft((i, j, clr))
                        continue
                    color[squares[i][j]] = clr
                    for a, b in [(i+1, j), (i-1, j), (i, j+1), (i, j-1)]:
                        if 0 <= a < height and 0 <= b < width and squares[a][b] == squares[i][j]:
                            q.appendleft((a, b, clr))

    path_length = {}
    for i in range(height):
        for j in range(width):
            if squares[i][j] not in path_length:
                q = [(squares[i][j], i, j)]
                while q:
                    clr, i, j = q.pop()
                    path_length[squares[i][j]] = min(path_length.get(squares[i][j], float('inf')), clr)
                    for a, b in [(i+1, j), (i-1, j), (i, j+1), (i, j-1)]:
                        if 0 <= a < height and 0 <= b < width and (a, b) not in q and squares[a][b] == clr:
                            q.append((squares[a][b], a, b))

    min_len = min(path_length.values() or [float('inf')])
    return min(len(color), min_len * 2)

def minimal_paint_time(n, m, slabs, width, height):
    if is_linked(slabs, width, height):
        return 0

    min_paint_times = float('inf')
    for i in range(1, width+1):
        for j in range(1, height+1):
            color = {}
            for square in slabs:
                if sum(ord(c) for c in square[:i]) - sum(ord(c) for c in square[i:m+j]) == ord(square[j-1]):
                    color[square] = 1
                    break
            for base in range(1, n+1):
                paint_time = 0
                for row in range(height):
                    for col in range(width):
                        paint_time += bfs(color, i, j) == bfs(slabs[row], base, base) and m*max(base, height//row+1)
                min_paint_times = min(min_paint_times, paint_time)
    return min_paint_times

