from collections import defaultdict

def max_candies(n, m, allowances):
    cache = defaultdict(lambda: -1)
    def dfs(i, mins):
        if i == n:
            return 0
        if mins <= 0:
            return 0
        if mins <= cache[(i, mins)]:
            return cache[(i, mins)]
        if not cache[(i, mins)]: 
            max_candies = 0
            for k in range(mins, m+1):
                max_candies = max(max_candies, (1 << i) + dfs(i+1, mins-k-1))
            cache[(i, mins)] = max_candies
            return max_candies
        else:
            return cache[(i, mins)]
    return dfs(1, n-1)

