def count_connected_components(mat):
    rows, cols = len(mat), len(mat[0])
    seen = set()

    def dfs(y, x):
        if (y, x) in seen:
            return 0
        component = 0
        stack = [(y, x)]
        while stack:
            y, x = stack.pop()
            if (y < 0 or y >= rows or x < 0 or x >= cols) or (mat[y][x] == 0 or (y, x) in seen):
                return 0
            seen.add((y, x))
            component += 1
            for dy, dx in [(-1, 0), (0, -1), (0, 1), (1, 0)]:
                ny, nx = y + dy, x + dx
                if (0 <= ny < rows and 0 <= nx < cols and mat[ny][nx] == 1 and (ny, nx) not in seen):
                    stack.append((ny, nx))
        return component

    component_count = 0
    for i in range(rows):
        for j in range(cols):
            if(mat[i][j] == 1) and (i, j) not in seen:
                component_count += dfs(i, j)
    return component_count

