from collections import defaultdict

def parse_rules(rules):
    # The keys are substrings of the string and the last character in the rule
    return {
        (rule[0][-1], rule[1][0], ord(rule[1][1]) - ord('a') + 1): (rule[2], int(rule[1][2]), int(rule[1][3]))
        for rule in rules.split()
    }

def find_good_substrings(s, rules):
    substrings = set()
    pattern_dict = defaultdict(list)

    # Preprocess rules for faster lookup
    for char, _, length in rules.values():
        for i in range(3, len(char), 5):
            pattern_dict[char[:i]].append(char[i-2:i])

    start = 0
    end = len(s)
    pattern_set = set()

    while start <= end:
        for pattern in pattern_dict.items():
            if s[start:end] == ''.join(pattern[0]):
                pattern_set.add('-'.join(pattern[0]))

        pattern_set.add(s[start:end])
        end += 1

    for pattern in pattern_set:
        found = False
        for p_length in range(2, len(pattern) + 2):
            for c_length, _ in rules.values():
                if pattern[:c_length - 1] == pattern[p_length:][:c_length - 1]:
                    if pattern[p_length - 3] not in '01':
                        continue
                    matches = [l for l in range(int(pattern[p_length - 2]), int(pattern[p_length - 1]) + 1) if c_length <= l <= p_length]
                    found = True
                    if not matches and p_length <= 3:
                        continue

                    substrings.add(pattern[p_length - 2:p_length])

        if not found:
            substrings.add(pattern)

    return len(substrings)

