def count_connected_components(matrix):
    # Create a set of cells to avoid counting the same component twice
    visited = set()

    # Initialize the list which keeps track of neighbors/connected cells
    neighbors = [[] for _ in range(len(matrix) * len(matrix[0]))]

    # Fill the neighbors list
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            value = matrix[i][j]
            if value == '1':
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < len(matrix) and 0 <= nj < len(matrix[0]) and matrix[ni][nj] == '1':
                        neighbors[ni * len(matrix[0]) + nj].append(i * len(matrix[0]) + j)

    # Depth-First Search to mark visited cells
    def dfs(cell):
        if cell in visited:
            return
        visited.add(cell)
        for neighbor in neighbors[cell]:
            dfs(neighbor)

    components = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if (i * len(matrix[0]) + j) not in visited and matrix[i][j] == '1':
                components += 1
                dfs(i * len(matrix[0]) + j)

    return components

