from collections import defaultdict

def parse_rules():
    rules = []
    for _ in range(int(input())):
        rule = input().split()
        rules.append(((rule[0]), int(rule[1]), int(rule[2])))
    return rules

def is_good(substring, rules):
    good = True
    occurrence = defaultdict(int)

    for rule in rules:
        # Only count pairs where the substring length >= rule length
        if len(substring) >= rule[1] - rule[0]:
            for i in range(rule[0], min(len(substring), rule[1])):
                occurrence[substring[i:rule[0]+i]] += 1

            for pos in range(rule[0], rule[1]):
                if occurrence[substring[pos:rule[0]+pos]] == 0:
                    good = False
            occurrence.clear()

    return good

def count_good_substrings(s, rules):
    size = 0
    # Compute substrings of all lengths that fit within s
    for length in range(1, min(50000, len(s) + 1)):
        for i in range(len(s) - length + 1):
            substring = s[i:i + length]
            if substring in rules[0][0]:
                size += 1

    # Use brute force, but pre-compute good substrings in advance
    good_substrings = list()
    for i in range(len(s)):
        for length in range(2, min(50000, len(s) - i + 1)):
            new_rule = rules[0][0].replace(s[i:i + length], "@")
            substring = s[i:i + length]
            good = is_good(substring, [new_rule])
            if good:
                good_substrings.append(substring)

    # Return the number of distinct good substrings
    return len(set(good_substrings))

