def find_good_mood(n, m, q):
    good_mood_cells = []
    previous_change = {(1, 1): False}

    for _ in range(q):
        a, l, r = map(int, input().split())
        previous_change[(a, l)] = not previous_change.get((a, l), False)
        for y in range(l, r + 1):
            if previous_change.get((a, y), False):
                good_mood_cells.append((1, y))
                good_mood_cells.append((n, y))

        if (a, l) in previous_change:
            good_mood_cells.append((a, l))
            good_mood_cells.append((a, r))

        print("-1" if good_mood_cells else " ".join(map(str, good_mood_cells)))
        good_mood_cells = []
        print(*sorted((cell) for cell in good_mood_cells))

