import sys
from collections import defaultdict

def bfs(graph, start):
    visited = {start}
    queue = [start]
    while queue:
        node = queue.pop(0)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return visited

def find_center(graph):
    centers = defaultdict(lambda: [0, sys.maxsize])
    for node in graph:
        if len(bfs(graph, node)) % 2 == 0:
            centers[node][0] = len(bfs(graph, node))
            centers[node][1] = len(bfs(graph, node)) // 2
    return next(iter(centers))

def perform_transformation(graph, start, y, y_prime):
    new_graph = defaultdict(set)
    for x, y_data in graph.items():
        dist_old = set()
        dist_new = set()
        for old_vertex, (old_dist_x, old_dist_y) in y_data.items():
            dist_old.add((old_vertex, old_dist_x, old_dist_y))
        for new_dist_x, new_dist_y in y_prime:
            new_graph[new_dist_x].add((x, new_dist_y, old_dist_x))
        for old_vertex, (old_dist_x, old_dist_y) in y_data.items():
            dist_new.add((x, old_dist_x, old_dist_y))
    transformed_graph = new_graph.copy()
    for old_vertex in graph.keys():
        new_vertex = y if node not in graph else y_prime[start - old_vertex + 1]
        transformed_graph[new_vertex].add((old_vertex, old_data[old_vertex][dist_old.index((old_vertex, old_data[old_vertex][0], old_data[old_vertex][1]))][dist_new.index((old_vertex, old_data[old_vertex][0], old_data[old_vertex][1]))]))
    return transformed_graph

