from math import inf

def overlap_exists(s, e):
    # Check if two intervals overlap
    return s <= e or e <= s or s == e

def max_overlap_subset(s_e_pairs, k_pairs):
    k_max = k_pairs[0][0]  # Take the max alien count for the minimum interval overlap
    result = 0
    for s, e in s_e_pairs:
        if s < e:
            result += 1  # Verify this only runs if they overlap
    n = set(k_pairs)
    for s, e in s_e_pairs:
        # Check which alien count subsets have this s and e
        for subset in combinations(k_pairs, k_max):
            if max(item[0] for item in subset) < s or min(item[1] for item in subset) > e:
                continue
            # Check if the subset isn't a superset of another set of size k_max
            if max(item[0] for item in subset) - min(item[1] for item in subset) > (e - s):
                result += 1
    return result

