def count_connection(row1, col1, row2, col2, matrix, component_count):
    if row1 < 0 or row1 >= len(matrix) or col1 >= len(matrix[0]) or col1 == row1:
        return
    if row2 < 0 or row2 >= len(matrix) or col2 >= len(matrix[0]) or col2 == row2:
        return
    if matrix[row1][col1] != '1':
        return
    if matrix[row2][col2] != '1':
        return

    matrix[row1][col1] = '0'
    matrix[row2][col2] = '0'
    count_connection(row1 - 1, col1, row2 - 1, col2, matrix, component_count)
    count_connection(row1 - 1, col2, row2 - 1, col1, matrix, component_count)
    count_connection(row1, col1 - 1, row2, col2, matrix, component_count)
    count_connection(row1, col2 - 1, row2, col1, matrix, component_count)

